      ro: "Un deal proeminent de cuarțită pe malul vestic al lacului Pielinen. Oferă o vedere panoramică asupra regiunii lacurilor finlandeze.",
      en: "A prominent quartzite hill on the western shore of Lake Pielinen. It provides extensive views over the Finnish Lakeland.",
