      ro: ["Înălțime aprox. 347 metri", "Parte a Parcului Național Koli", "Subiect al romantismului național", "Geologie de cuarțită"],
      en: ["Height approx. 347 meters", "Part of Koli National Park", "Classic theme in national romantic art", "Quartzite geology"],
      es: ["Altura aprox. 347 metros", "Parte del Parque Nacional de Koli", "Motivo famoso del romanticismo nacional", "Geología de cuarcita"],
      pt: ["Altura aprox. 347 metros", "Parte do Parque Nacional de Koli", "Motivo famoso do romantismo nacional", "Geologia de quartzito"],
