      en: ["Oldest nature reserve in Finland", "Hilly forest landscape", "Limited access", "Scientifically valuable"],
      es: ["Reserva natural más antigua de Finlandia", "Paisaje forestal montañoso", "Acceso limitado", "Científicamente valioso"],
      pt: ["Reserva natural mais antiga da Finlândia", "Paisagem florestal montanhosa", "Acesso limitado", "Cientificamente valioso"],
      fr: ["Plus ancienne réserve naturelle de Finlande", "Paysage forestier vallonné", "Accès limité", "Valeur scientifique"],
