      es: ["Altura: 600 m", "Roca: Cuarcita", "Tiempo de ascenso: 3 horas (ida)", "Ave más frecuente: Chorlito dorado", "Altura media de la nieve en febrero: 70 cm", "Número de senderos marcados: 2"],
      pt: ["Altura: 600 m", "Rocha: Quartzito", "Tempo de subida: 3 horas (ida)", "Ave mais comum: Tarambola-dourada", "Altura média da neve em fevereiro: 70 cm", "Número de trilhos marcados: 2"],
      fr: ["Altitude : 600 m", "Roche : Quartzite", "Temps d'ascension : 3 heures (aller simple)", "Oiseau le plus commun : Pluvier doré", "Épaisseur moyenne de neige en février : 70 cm", "Nombre de sentiers balisés : 2"],
