    facts: {
      de: ["Flusslandschaft", "Typisch Lappland", "Naturbelassen", "Wanderrouten"],
      hu: ["Folyami táj", "Tipikus Lappföld", "Természetes", "Túraútvonalak"],
      ro: ["Peisaj fluvial", "Tipic Laponia", "Natural", "Trasee de drumeție"],
      en: ["River landscape", "Typical Lapland", "Natural", "Hiking routes"],
      es: ["Paisaje fluvial", "Típico de Laponia", "Natural", "Rutas de senderismo"],
      pt: ["Paisagem fluvial", "Típico da Lapônia", "Natural", "Rotas de caminhada"],
      fr: ["Paysage fluvial", "Typique de la Laponie", "Sauvage", "Sentiers de randonnée"],
    },
    imageHint: "Isokurkkio valley landscape",
    descriptionAdvanced: {
      de: "Das Isokurkkio-Tal liegt im Nordwesten Finnlands, tief in der Wildnis von Enontekiö. Es ist bekannt für seine beeindruckenden Schluchten und Stromschnellen, die durch den Fluss Pöyrisjoki geformt wurden. Der Name 'Isokurkkio' leitet sich aus dem Finnischen ab und bedeutet 'große Kehle', was auf die enge und tiefe Struktur des Tals hinweist. Geologisch wurde das Tal während des Rückzugs der eiszeitlichen Gletscher vor etwa 10.000 Jahren tief in den Fels geschnitten. Die steilen Hände des Tals sind mit kargen Birkenwäldern bewachsen, während am Talboden eine feuchtigkeitsliebende Flora gedeiht. Das Isokurkkio-Tal ist ein wichtiger Lebensraum für die arktische Forelle und andere Fischarten, die in den sauerstoffreichen Stromschnellen laichen. Aufgrund seiner Abgeschiedenheit ist das Tal nur nach mehrtägigen Wanderungen erreichbar und gilt als Geheimtipp für Naturfotografen und Wildnis-Abenteurer.",
      hu: "Az Isokurkkio-völgy Finnország északnyugati részén, Enontekiö vadonjának mélyén található. Lenyűgöző szurdokairól és zúgóiról ismert, amelyeket a Pöyrisjoki folyó formált az évezredek során. Az 'Isokurkkio' név a finn nyelvből származik, jelentése 'nagy torok', ami a völgy szűk és mély szerkezetére utal. Földtanilag a völgyet a jégkorszaki gleccserek visszahúzódása során, körülbelül 10 000 évvel ezelőtt vájta a víz a kőzetbe. A völgy meredek oldalai ritkás nyírferdőkkel borítottak, míg a völgy alján nedvességkedvelő flóra tenyészik. Az Isokurkkio-völgy fontos élőhelye az arktikus pisztrángnak és más halfajoknak, amelyek az oxigéndús zúgókban ívnak. Elszigeteltsége miatt a völgy csak többnapos túrával érthető el, és a természetfotósok, valamint a vadon kalandorainak titkos tippjeként tartják számon.",
      ro: "Valea Isokurkkio este situată în nord-vestul Finlandei, adânc în sălbăticia din Enontekiö. Este cunoscută pentru defileele și repezișurile sale impresionante, formate de râul Pöyrisjoki de-a lungul mileniilor. Numele 'Isokurkkio' provine din limba finlandeză și înseamnă 'gâtul mare', făcând referire la structura îngustă și adâncă a văii. Din punct de vedere geologic, valea a fost tăiată adânc în stâncă în timpul retragerii ghețarilor de la sfârșitul epocii glaciare, acum aproximativ 10.000 de ani. Versanții abrupți ai văii sunt acoperiți de păduri rare de mesteacăn, în timp ce pe fundul văii prosperă o floră iubitoare de umiditate. Valea Isokurkkio este un habitat important pentru păstrăvul arctic și alte specii de pești care depun icre în repezișurile bogate în oxigen. Din cauza izolării sale, valea este accesibilă doar după drumeții de câteva zile, fiind considerată un loc deosebit pentru fotografii de natură și aventurierii sălbăticiei.",
      en: "Isokurkkio Valley is located in northwestern Finland, deep within the wilderness of Enontekiö. It is renowned for its impressive gorges and rapids, carved over millennia by the Pöyrisjoki River. The name 'Isokurkkio' is derived from Finnish and means 'great throat,' referring to the narrow and deep structure of the valley. Geologically, the valley was cut deep into the rock during the retreat of glacial ice sheets approximately 10,000 years ago. The steep slopes of the valley are covered with sparse birch forests, while the valley floor supports moisture-loving flora. Isokurkkio Valley is a vital habitat for arctic trout and other fish species that spawn in the oxygen-rich rapids. Due to its extreme remoteness, the valley is accessible only after multi-day treks and is considered a hidden gem for nature photographers and wilderness adventurers.",
      es: "El valle de Isokurkkio es un valle profundo formado por glaciares en el Parque Nacional Pallas-Yllästunturi, en el oeste de Laponia. Tiene unos 2 km de largo y hasta 100 m de profundidad. El nombre significa 'gran pasaje estrecho' en finlandés. El valle está rodeado de paredes rocosas escarpadas con cascadas y conos de derrubios. La vegetación incluye líquenes, musgos y árboles dispersos. Isokurkkio es un destino popular para excursionistas que aprecian la belleza natural y el aislamiento. El valle es hábitat del águila real y otras aves rapaces.",
      pt: "O vale de Isokurkkio é um vale profundo formado por glaciares no Parque Nacional Pallas-Yllästunturi, no oeste da Lapônia. Tem cerca de 2 km de comprimento e até 100 m de profundidade. O nome significa 'grande passagem estreita' em finlandês. O vale está cercado por paredes rochosas escarpadas com cascatas e cones de dejetos. A vegetação inclui líquenes, musgos e árvores dispersas. Isokurkkio é um destino popular para caminhantes que apreciam a beleza natural e o isolamento. O vale é habitat da águia-real e outras aves de rapina.",
      fr: "La vallée d'Isokurkkio est une vallée profonde façonnée par les glaciers dans le parc national de Pallas-Yllästunturi, en Laponie occidentale. Elle mesure environ 2 km de long et jusqu'à 100 m de profondeur. Le nom signifie « grand passage étroit » en finnois. La vallée est entourée de parois rocheuses abruptes marquées par des cascades et des cônes de déjection. La végétation comprend des lichens, des mousses et des arbres clairsemés. Isokurkkio est une destination prisée des randonneurs qui apprécient la beauté naturelle et l'isolement. La vallée est l'habitat de l'aigle royal et d'autres rapaces.",
    },
