      ro: ["Situat în municipalitatea Pelkosenniemi", "Compoziție geologică dominantă de cuarțit", "Parte a dealurilor din estul Laponiei centrale", "Numele se traduce prin 'Muntele Epuizării'", "Oferă panoramă spre masivul Pyhä-Luosto", "Zonă tradițională pentru culesul fructelor de pădure"],
