      es: ["Altura de 490 metros", "Centro de deportes de invierno", "Región de Kuusamo", "Popular entre los turistas"],
      pt: ["Altitude de 490 metros", "Centro de desportos de inverno", "Região de Kuusamo", "Popular entre os turistas"],
      fr: ["Altitude 490 mètres", "Centre de sports d'hiver", "Région de Kuusamo", "Apprécié des touristes"],
