    imageHint: "Pyhavaara hill Ruka",
    descriptionAdvanced: {
      de: "Pyhävaara ist ein markanter Hügel südlich von Ruka in Kuusamo, der eine Höhe von 460 Metern erreicht. Sein Name bedeutet übersetzt Heiliger Berg, was auf seine historische Bedeutung als Kultstätte für die indigenen Samen hinweist. Der Berg ist Teil eines größeren Schutzgebietes, das für seine unberührten Primärwälder bekannt ist, in denen einige Bäume über 300 Jahre alt sind. Geologisch besteht Pyhävaara aus resistentem Quarzit, der als Überrest eines uralten Gebirgszuges die Landschaft dominiert. Wanderwege führen durch abwechslungsreiches Gelände, vorbei an steilen Klippen und durch dichte Nadelwälder zum Gipfel. Von oben bietet sich ein Blick auf die sanften Hügelketten des Kuusamo-Hochlandes und zahlreiche Seen. Pyhävaara gilt als ökologisch wertvoll, da er Lebensraum für viele bedrohte Moos- und Flechtenarten bietet. Im Winter ist der Berg ein ruhiges Ziel für Schneeschuhwanderer, weitab vom Trubel des nahen Skigebietes Ruka. Die spirituelle Atmosphäre des Ortes ist bis heute spürbar und macht ihn zu einem besonderen kulturellen Denkmal der Region.",
      hu: "A Pyhävaara egy jellegzetes domb Rukától délre, Kuusamóban, amely 460 méteres magasságot ér el. Neve Szent Hegyet jelent, ami az őslakos számik számára betöltött rituális és kultikus jelentőségére utal. A hegy egy nagyobb védett terület része, amely érintetlen őserdőiről ismert, ahol egyes fák kora meghaladja a 300 évet. Földtanilag a Pyhävaara ellenálló kvarcitból áll, amely egy ősi hegylánc maradványaként uralja a tájat. Túraútvonalak vezetnek változatos terepen, meredek sziklák mellett és sűrű fenyveseken keresztül a csúcsra. A tetőről kilátás nyílik a kuusamói felföld lankás dombsoraira és számos tóra. A Pyhävaara ökológiailag rendkívül értékes, mivel számos veszélyeztetett moha- és zuzmófajnak ad otthont. Télen a hegy a hótalpas túrázók kedvelt, csendes célpontja, távol a közeli Ruka síközpont nyüzsgésétől. A hely spirituális atmoszférája a mai napig érezhető, így a régió különleges kulturális emlékhelye.",
      ro: "Pyhävaara este un deal proeminent situat la sud de Ruka, în Kuusamo, atingând o înălțime de 460 de metri. Numele său se traduce prin Muntele Sfânt, ceea ce indică importanța sa istorică ca loc de cult pentru populația indigenă Sami. Muntele face parte dintr-o zonă protejată mai mare, cunoscută pentru pădurile sale primare neatinse, unde unii copaci au o vechime de peste 300 de ani. Din punct de vedere geologic, Pyhävaara este compus din cuarțit rezistent, care domină peisajul ca o rămășiță a unui lanț muntos străvechi. Traseele de drumeție duc prin teren variat, pe lângă stânci abrupte și prin păduri dense de conifere către vârf. De sus, se oferă o vedere asupra lanțurilor de dealuri blânde ale podișului Kuusamo și asupra numeroaselor lacuri. Pyhävaara este considerat valoros din punct de vedere ecologic, deoarece oferă habitat pentru multe specii de mușchi și licheni pe cale de dispariție. Iarna, muntele este o destinație liniștită pentru drumețiile cu rachete de zăpadă, departe de agitația stațiunii de schi Ruka din apropiere. Atmosfera spirituală a locului este sesizabilă și astăzi, făcându-l un monument cultural special al regiunii.",
      en: "Pyhävaara is a prominent hill south of Ruka in Kuusamo, reaching an elevation of 460 meters. Its name translates to Holy Fell, pointing to its historical significance as a cult site for the indigenous Sami people. The mountain is part of a larger protected area known for its untouched primary forests, where some trees are over 300 years old. Geologically, Pyhävaara consists of resistant quartzite, dominating the landscape as a remnant of an ancient mountain range. Hiking trails lead through varied terrain, past steep cliffs and through dense coniferous forests to the summit. From the top, views over the gentle hill chains of the Kuusamo highlands and numerous lakes are offered. Pyhävaara is considered ecologically valuable as it provides habitat for many endangered moss and lichen species. In winter, the mountain is a quiet destination for snowshoe hikers, far from the hustle and bustle of the nearby Ruka ski resort. The spiritual atmosphere of the place is still palpable today, making it a special cultural monument of the region.",
      es: "La montaña de 461 metros cerca de Ruka se considera un lugar sagrado para los Sámi. La ruta de senderismo 'Pyhän Jyssäys' conduce a la cumbre y ofrece vistas de la región de los lagos de Kuusamo.",
      pt: "A montanha de 461 metros perto de Ruka é considerada um lugar sagrado para os Sámi. A trilha de caminhada 'Pyhän Jyssäys' leva ao cume e oferece vistas da região dos lagos de Kuusamo.",
      fr: "La montagne de 461 mètres près de Ruka est considérée comme un lieu sacré pour les Sames. Le sentier de randonnée « Pyhän Jyssäys » mène au sommet et offre une vue sur la région des lacs de Kuusamo.",
    },
    factsAdvanced: {
      de: ["Die absolute Höhe des Pyhävaara beträgt 460 Meter.", "Der Name stammt aus der samischen Sprache und bedeutet Heiliger Ort.", "Einige Kiefern im Gebiet sind nachweislich über 300 Jahre alt.", "Der Berg gehört zum Valtavaara-Pyhävaara-Naturschutzgebiet.", "Der Pyhän Jyssäys ist ein beliebter 6 km langer Wanderweg auf den Gipfel.", "Die Felsen weisen Spuren von Seiden auf, alten samischen Opferstätten."],
      hu: ["A Pyhävaara abszolút magassága 460 méter.", "A név a számi nyelvből származik, és szent helyet jelent.", "A területen található egyes erdeifenyők bizonyítottan 300 évnél idősebbek.", "A hegy a Valtavaara-Pyhävaara természetvédelmi területhez tartozik.", "A Pyhän Jyssäys egy népszerű 6 km-es túraútvonal a csúcsra.", "A sziklákon szeidák, azaz ősi számi áldozati helyek nyomai fedezhetők fel."],
      ro: ["Înălțimea absolută a Pyhävaara este de 460 de metri.", "Numele provine din limba Sami și înseamnă Loc Sfânt.", "S-a dovedit că unii pini din zonă au o vechime de peste 300 de ani.", "Muntele aparține rezervației naturale Valtavaara-Pyhävaara.", "Pyhän Jyssäys este un traseu de drumeție popular de 6 km către vârf.", "Stâncile prezintă urme de seite, vechi locuri de sacrificiu Sami."],
      en: ["The absolute height of Pyhävaara is 460 meters.", "The name originates from the Sami language and means Holy Place.", "Some pine trees in the area are proven to be over 300 years old.", "The fell belongs to the Valtavaara-Pyhävaara nature reserve.", "The Pyhän Jyssäys is a popular 6 km hiking trail to the summit.", "The rocks show traces of seidas, ancient Sami sacrificial sites."],
      es: ["Altura: 461 metros", "Ubicación: Ruka, Kuusamo", "Importancia: Lugar sagrado", "Ruta de senderismo: Pyhän Jyssäys"],
      pt: ["Altitude: 461 metros", "Localização: Ruka, Kuusamo", "Significado: Lugar sagrado", "Trilha de caminhada: Pyhän Jyssäys"],
      fr: ["Altitude : 461 mètres", "Lieu : Ruka, Kuusamo", "Importance : Lieu sacré", "Sentier de randonnée : Pyhän Jyssäys"],
    },
    image: "/poi-images/finland-pyhavaara-relief-v2.webp",
