      ro: ["Tundră arctică", "Podiș", "Regiune de drumeție", "Foarte solitar"],
      en: ["Arctic tundra", "Highland", "Hiking region", "Very solitary"],
      es: ["Tundra ártica", "Tierras altas", "Región de senderismo", "Muy solitario"],
      pt: ["Tundra ártica", "Terras altas", "Região de caminhadas", "Muito solitário"],
      fr: ["Toundra arctique", "Hauts plateaux", "Région de randonnée", "Très sauvage"],
