    imageHint: "Tuntsa forest landscape",
    descriptionAdvanced: {
      de: "Das Tuntsa-Wildnisgebiet im Osten Lapplands ist bekannt für seine dramatische Geschichte und seine einzigartige, karge Schönheit. Im Jahr 1960 wütete hier der größte Waldbrand in der modernen Geschichte Finnlands, der weite Teile der ursprünglichen Nadelwälder vernichtete und eine offene, parkähnliche Landschaft hinterließ. Geografisch liegt Tuntsa in den Gemeinden Salla und Savukoski, direkt an der russischen Grenze. Die Region ist geprägt von sanften Hügeln, sogenannten Vaaras, und tiefen Schluchten wie dem Tuntsajoki-Tal. Diese Abgeschiedenheit macht Tuntsa zu einem wichtigen Lebensraum für das europäische Rentier und verschiedene Greifvogelarten. Wanderer schätzen das Gebiet für seine Ruhe und die weite Sicht, die durch den langsamen Regenerationsprozess der Vegetation nach dem Feuer begünstigt wird.",
      hu: "A kelet-lappföldi Tuntsa vadon drámai történelméről és egyedülálló, zord szépségéről ismert. 1960-ban itt pusztított Finnország modern történetének legnagyobb erdőtüze, amely az eredeti fenyőerdők hatalmas részét megsemmisítette, és nyitott, parkszerű tájat hagyott maga után. Földrajzilag Tuntsa Salla és Savukoski községekben található, közvetlenül az orosz határ mentén. A régiót lankás dombok (úgynevezett vaarák) és mély szurdokok jellemzik, mint például a Tuntsajoki völgye. Ez az elszigeteltség teszi Tuntsát az európai rénszarvas és különféle ragadozómadár-fajok fontos élőhelyévé. A túrázók a nyugalom és a tűz utáni lassú növényzeti regeneráció által lehetővé vált tágas kilátás miatt kedvelik a területet.",
      ro: "Zona sălbatică Tuntsa din estul Laponiei este cunoscută pentru istoria sa dramatică și frumusețea sa aridă unică. În anul 1960, aici a avut loc cel mai mare incendiu forestier din istoria modernă a Finlandei, care a distrus porțiuni vaste din pădurile de conifere originale și a lăsat în urmă un peisaj deschis, asemănător unui parc. Geografic, Tuntsa este situată în comunele Salla și Savukoski, chiar la granița cu Rusia. Regiunea este caracterizată de dealuri domoale, numite 'vaara', și văi adânce, precum valea Tuntsajoki. Această izolare face din Tuntsa un habitat important pentru renul european și diverse specii de păsări de pradă. Drumeții apreciază zona pentru liniștea sa și vizibilitatea extinsă, favorizată de procesul lent de regenerare a vegetației după incendiu.",
      en: "The Tuntsa Wilderness Area in eastern Lapland is known for its dramatic history and unique, barren beauty. In 1960, it was the site of the largest forest fire in Finland's modern history, which destroyed vast portions of the original coniferous forests and left behind an open, park-like landscape. Geographically, Tuntsa is located in the municipalities of Salla and Savukoski, directly on the Russian border. The region is characterized by gently sloping hills, known as 'vaaras', and deep gorges such as the Tuntsajoki valley. This remoteness makes Tuntsa an important habitat for European reindeer and various species of birds of prey. Hikers value the area for its tranquility and the broad views facilitated by the slow regeneration process of the vegetation following the fire.",
      es: "El desierto de Tuntsa es una extensa área silvestre en el este de Finlandia, cerca de la frontera rusa. Abarca 500 km² y forma parte de la reserva establecida en 1992. El paisaje está dominado por colinas boscosas y turberas. La mayor elevación alcanza los 450 metros. La zona es hogar de osos pardos, lobos y renos. No hay carreteras, solo senderos para excursionistas y motos de nieve, siendo uno de los últimos refugios de naturaleza pura en Finlandia.",
      pt: "A área selvagem de Tuntsa é uma vasta região deserta no leste da Finlândia, perto da fronteira russa. Abrange uma área de 500 km² e faz parte da área estabelecida em 1992. A paisagem é dominada por colinas arborizadas e pântanos. O ponto mais alto atinge os 450 metros. A área abriga ursos pardos, lobos e renas. Não há estradas, apenas trilhas para caminhantes e motoneves, sendo um dos últimos refúgios de natureza intocada na Finlândia.",
      fr: "La région sauvage de Tuntsa est une vaste zone déserte de l'est de la Finlande, proche de la frontière russe. Elle couvre 500 km² et fait partie de la zone protégée établie en 1992. Le paysage est dominé par des collines boisées et des tourbières. Le point culminant atteint 450 mètres. La région abrite des ours bruns, des loups et des rennes. Sans routes, elle ne dispose que de sentiers pour les randonneurs et les motoneiges, constituant l'un des derniers refuges de nature vierge en Finlande.",
    },
    factsAdvanced: {
      de: ["Der Waldbrand von 1960 zerstörte über 20.000 Hektar Waldfläche.", "Tuntsa gilt als eines der am schwierigsten zugänglichen Wandergebiete Finnlands.", "Der Hügel Nuorttitunturi ist eine der bekanntesten Erhebungen der Region.", "Das Gebiet beherbergt seltene Flechtenarten, die auf dem verbrannten Boden gedeihen.", "Die Staatsgrenze zu Russland verläuft direkt östlich des Wildnisgebiets.", "Die Region ist ein wichtiger Teil des Grünen Bandes von Fennoskandien."],
      hu: ["Az 1960-as erdőtűz több mint 20 000 hektárnyi erdőterületet pusztított el.", "Tuntsa Finnország egyik legnehezebben megközelíthető túraútvonalának számít.", "A Nuorttitunturi domb a régió egyik legismertebb kiemelkedése.", "A területen ritka zuzmófajok találhatók, amelyek a megégett talajon fejlődnek.", "Az orosz államhatár közvetlenül a vadon területétől keletre húzódik.", "A régió fontos részét képezi Fennoskandia Zöld Övezetének."],
      ro: ["Incendiul de pădure din 1960 a distrus peste 20.000 de hectare de pădure.", "Tuntsa este considerată una dintre cele mai greu accesibile zone de drumeție din Finlanda.", "Dealul Nuorttitunturi este una dintre cele mai cunoscute ridicături din regiune.", "Zona găzduiește specii rare de licheni care prosperă pe solul ars.", "Granița de stat cu Rusia trece direct la est de zona sălbatică.", "Regiunea este o parte importantă a Centurii Verzi a Fennoscandiei."],
      en: ["The 1960 forest fire destroyed over 20,000 hectares of forest land.", "Tuntsa is considered one of the most challenging hiking areas to access in Finland.", "Nuorttitunturi hill is one of the most well-known elevations in the region.", "The area is home to rare lichen species that thrive on the scorched soil.", "The state border with Russia runs directly to the east of the wilderness area.", "The region is an important part of the Green Belt of Fennoscandia."],
      es: ["El área silvestre de Tuntsa abarca 500 km².", "Fue establecida en 1992.", "La elevación más alta es de 450 m.", "La densidad de población es de 0 habitantes por km².", "El río Tuntsa tiene 100 km de largo.", "La precipitación anual es de 600 mm."],
      pt: ["A área selvagem de Tuntsa abrange 500 km².", "Foi estabelecida em 1992.", "A altitude máxima é de 450 m.", "A densidade populacional é de 0 habitantes por km².", "O rio Tuntsa tem 100 km de comprimento.", "A precipitação anual é de 600 mm."],
      fr: ["La zone sauvage de Tuntsa couvre 500 km².", "Elle a été créée en 1992.", "Le point culminant est de 450 m.", "La densité de population est de 0 habitant au km².", "La rivière Tuntsa mesure 100 km de long.", "Les précipitations annuelles sont de 600 mm."],
    },
