      pt: "Uma cordilheira de colinas na Lapônia Ocidental. Situa-se numa região famosa pelos seus trilhos de caminhada.",
      fr: "Une chaîne de collines en Laponie occidentale. Elle est située dans une région célèbre pour ses sentiers de randonnée.",
